        :rtype: str
        """
        alpha_list = []
        num_list = []
        for c in s:
            if c.isdigit():
                num_list.append(c)
            else:
                alpha_list.append(c)
        if abs(len(alpha_list) - len(num_list)) > 1:
            return ""
        ans = ""
        if len(alpha_list) - len(num_list) == 1:
            for i in range(len(num_list)):
                ans += alpha_list[i]
                ans += num_list[i]
            ans += alpha_list[-1]
        elif len(num_list) - len(alpha_list) == 1:
            for i in range(len(alpha_list)):
                ans += num_list[i]
                ans += alpha_list[i]
            ans += num_list[-1]
        else:
            for i in range(len(num_list)):
                ans += num_list[i]
                ans += alpha_list[i]
        return ans
